using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Net;
using System.Net.Sockets;
using System.Threading.Tasks;
namespace BF4Bots {public static class RotationMock {
 static byte[] Read(Stream s,int n){var b=new byte[n];int p=0;while(p<n){int got=s.Read(b,p,n-p);if(got==0)throw new EndOfStreamException();p+=got;}return b;}
 public static void Run(){string fixture=Path.Combine(Path.GetTempPath(),"BF4LocalRotation-"+Guid.NewGuid().ToString("N"));string mapFile=Path.Combine(fixture,"Server\\Instance\\Admin\\MapList.txt");Directory.CreateDirectory(Path.GetDirectoryName(mapFile));File.WriteAllText(mapFile,"XP0_Metro ConquestLarge0 1\r\n");var listener=new TcpListener(IPAddress.Loopback,0);listener.Start();int port=((IPEndPoint)listener.LocalEndpoint).Port;var maps=new List<RotationEntry>{new RotationEntry{Map="XP0_Metro",Mode="ConquestLarge0",Rounds=1}};string activeMap="XP0_Metro",activeMode="ConquestLarge0",serverName="fixture";int switches=0;var server=Task.Run(()=>{try{using(var client=listener.AcceptTcpClient())using(var stream=client.GetStream()){stream.ReadTimeout=6000;while(true){var head=Read(stream,12);int size=(int)BitConverter.ToUInt32(head,4);var packet=head.Concat(Read(stream,size-12)).ToArray();var words=Rcon.Decode(packet);string[] result;switch(words[0]){case "login.hashed":result=words.Length==1?new[]{"OK","00112233445566778899AABBCCDDEEFF"}:new[]{"OK"};break;case "mapList.list":var output=new List<string>{"OK",maps.Count.ToString(),"3"};foreach(var m in maps){output.Add(m.Map);output.Add(m.Mode);output.Add(m.Rounds.ToString());}result=output.ToArray();break;case "mapList.clear":maps.Clear();result=new[]{"OK"};break;case "mapList.add":if(words[1]=="FAIL")result=new[]{"InvalidMapName"};else{maps.Add(new RotationEntry{Map=words[1],Mode=words[2],Rounds=Int32.Parse(words[3])});result=new[]{"OK"};}break;case "mapList.load":var loaded=File.ReadAllLines(mapFile).Where(line=>!String.IsNullOrWhiteSpace(line)).Select(line=>line.Split(new[]{' '},StringSplitOptions.RemoveEmptyEntries)).Select(parts=>new RotationEntry{Map=parts[0],Mode=parts[1],Rounds=Int32.Parse(parts[2])}).ToList();if(loaded.Any(x=>x.Map=="FAIL"))result=new[]{"InvalidMapName"};else{maps.Clear();maps.AddRange(loaded);result=new[]{"OK"};}break;case "serverInfo":result=new[]{"OK",serverName,"0","66",activeMode,activeMap};break;case "mapList.setNextMapIndex":result=new[]{"OK"};break;case "mapList.runNextRound":activeMap=maps[0].Map;activeMode=maps[0].Mode;switches++;result=new[]{"OK"};break;case "vars.serverName":serverName=words[1];result=new[]{"OK"};break;case "mapList.save":result=new[]{"OK"};break;default:result=new[]{"UnknownCommand"};break;}var reply=Rcon.Encode(BitConverter.ToUInt32(packet,0)|0x40000000,result);stream.Write(reply,0,reply.Length);}}}catch(EndOfStreamException){}finally{listener.Stop();}});
 using(var r=new Rcon()){r.Connect("127.0.0.1",port,"fixture-password");var original=r.Maps();var next=new List<RotationEntry>{new RotationEntry{Map="MP_Prison",Mode="ConquestLarge0",Rounds=2}};string temp=Path.Combine(Path.GetTempPath(),"BF4Rotation-tests-"+Guid.NewGuid().ToString("N"));r.SaveRotation(original,next,Path.Combine(temp,"before.json"));if(!Rcon.Same(next,r.Maps()))throw new Exception("Falha ao salvar rotação simulada");MapNow.SwitchAndWait(r,next[0],"Offline - Operation Locker");MapNow.SwitchAndWait(r,next[0],"Offline - Operation Locker");if(switches!=1||r.Command("serverInfo")[1]!="Offline - Operation Locker")throw new Exception("Troca imediata ou reaproveitamento incorreto");bool failed=false;try{r.SaveRotation(next,new List<RotationEntry>{new RotationEntry{Map="FAIL",Mode="ConquestLarge0",Rounds=1}},Path.Combine(temp,"rollback.json"));}catch(IOException){failed=true;}if(!failed||!Rcon.Same(next,r.Maps()))throw new Exception("Falha ao restaurar após rejeição de mapa");failed=false;try{r.SaveRotation(original,next,Path.Combine(temp,"stale.json"));}catch(IOException){failed=true;}if(!failed||!Rcon.Same(next,r.Maps()))throw new Exception("Não rejeitou rotação desatualizada");var wantedLocal=new List<RotationEntry>{new RotationEntry{Map="MP_Abandoned",Mode="ConquestLarge0",Rounds=1}};LocalRotation.Save(fixture,r,next,wantedLocal,Path.Combine(temp,"local.json"));if(!Rcon.Same(wantedLocal,r.Maps()))throw new Exception("Arquivo local não foi carregado");byte[] persisted=File.ReadAllBytes(mapFile);failed=false;try{LocalRotation.Save(fixture,r,wantedLocal,new List<RotationEntry>{new RotationEntry{Map="FAIL",Mode="ConquestLarge0",Rounds=1}},Path.Combine(temp,"local-failure.json"));}catch(IOException){failed=true;}if(!failed||!Rcon.Same(wantedLocal,r.Maps())||Config.Hash(persisted)!=Config.Hash(File.ReadAllBytes(mapFile)))throw new Exception("Rollback de arquivo/runtime falhou");}if(!server.Wait(7000))throw new Exception("Servidor simulado não encerrou.");if(server.IsFaulted)throw server.Exception;
 }
